import { loader, multiple } from 'fumadocs-core/source';
import { llms } from 'fumadocs-core/source/llms';
import { createFromSource } from 'fumadocs-core/search/server';
import { createOpenAPI } from 'fumadocs-openapi/server';
import { readFileSync } from 'node:fs';
import path from 'node:path';
// Generated by `yarn prepare-docs` + fumadocs-mdx (dev/build regenerate it).
import { docs } from '../../.source/server';

export const openapi = createOpenAPI({
  input: [path.resolve(process.cwd(), '../../docs/openapi/public-api-v1.json')],
});

const apiSource = await openapi.staticSource({
  per: 'operation',
  groupBy: () => 'api-reference',
  // Route-shaped slugs (`api-reference/v1/sessions/get`) instead of Nest operationIds;
  // the spec paths carry the `/api` mount prefix, which the docs tree doesn't need.
  name(entry) {
    if (entry.type === 'operation') {
      return `${this.routePathToFilePath(entry.item.path).replace(/^api\//, '')}/${entry.item.method.toLowerCase()}`;
    }
    return 'index';
  },
});

export const source = loader({
  baseUrl: '/',
  source: multiple({ docs: docs.toFumadocsSource(), api: apiSource }),
  plugins: [openapi.loaderPlugin()],
});

/** Static Orama index served at /search-index on the docs host. */
export const docsSearch: ReturnType<typeof createFromSource> = createFromSource(source);

/** llms.txt rendering helpers. */
export const docsLlms = llms(source as unknown as Parameters<typeof llms>[0], {
  renderPage: async (page) => {
    const data = page.data as { getText?: (type: 'raw' | 'processed') => Promise<string> };
    return (await data.getText?.('processed')) ?? '';
  },
});

export interface GitInfo {
  path: string;
  lastModified: string | null;
}

/** Last-commit dates, generated by prepare-docs.mjs; empty when git history is missing. */
function loadGitInfo(): Record<string, GitInfo> {
  try {
    return JSON.parse(readFileSync(path.join(process.cwd(), 'lib/docs/git-info.json'), 'utf8'));
  } catch {
    return {};
  }
}
const INFO = loadGitInfo();

/** git history metadata for a docs page slug, keyed the way `prepare-docs.mjs` wrote it. */
export function pageGitInfo(slugs: string[] | undefined): GitInfo | null {
  return INFO[(slugs ?? []).join('/')] ?? null;
}
